const pkg = $input.first().json;
const images = ((pkg.product || {}).images) || [];
if (!images.length) throw new Error('上架包里没有图片（v3 契约 images 为空）');
return images.map((img) => ({ json: img }));

const pkg = $('取数-上架包').first().json;
const metas = $('拆图').all().map((i) => i.json);
const medias = $input.all().map((i) => i.json);
const p = pkg.product || {};
const price = p.price || {};
const stock = p.stock || {};
const desc = p.description || {};
const category = p.category || {};
const seo = p.seo || {};
let html = desc.html || '';
const gallery = [];
metas.forEach((m, idx) => {
  const media = medias[idx] || {};
  if (m.placement === 'description' && m.embed_token) {
    if (media.source_url) {
      html = html.split(m.embed_token).join(media.source_url);
    }
  } else if (media.id != null) {
    gallery.push({ id: media.id });
  }
});
const leftover = (html.match(/\{\{KP_IMG_\d+\}\}/g) || []);
if (leftover.length) throw new Error('描述图占位符未替换: ' + leftover.join(','));
const body = {
  name: p.title || '',
  type: 'simple',
  sku: p.sku || '',
  regular_price: price.regular != null ? String(price.regular) : '',
  description: html,
  short_description: '',
  manage_stock: false,
  stock_status: stock.status === 'out_of_stock' ? 'outofstock' : 'instock',
  images: gallery,
  meta_data: [],
};
if (price.sale != null) body.sale_price = String(price.sale);
// 重推(SKU 已存在)时不改 status——已发布的保持发布;只有首次新建才落草稿等人工发布。
const existingProductId = pkg.woo_existing_product_id || (pkg.product || {}).woo_existing_product_id;
if (!existingProductId) {
  body.status = 'draft';
}
// K 的 SEO 文案是唯一 meta 来源；禁止从描述 HTML 剥标签/截断生成。
const seoTitle = typeof seo.title === 'string' ? seo.title.trim() : '';
const seoDescriptionCandidate = (
  typeof seo.meta_description === 'string' && seo.meta_description.trim()
) ? seo.meta_description : seo.description;
const seoDescription = typeof seoDescriptionCandidate === 'string'
  ? seoDescriptionCandidate.trim()
  : '';
const seoUrlSlug = typeof seo.url_slug === 'string' ? seo.url_slug.trim() : '';
if (seoTitle) {
  body.meta_data.push({ key: '_yoast_wpseo_title', value: seoTitle });
}
if (seoDescription) {
  body.meta_data.push({ key: '_yoast_wpseo_metadesc', value: seoDescription });
}
// Woo permalink only accepts K's short SEO slug; never derive it from the H1.
if (seoUrlSlug) {
  body.slug = seoUrlSlug;
}
// 买家类目已由控制台确保；这里只引用有效叶子 ID。
// 缺失时不写 categories，避免更新已有产品时清空其类目。
const wcCategoryId = Number(category.wc_category_id);
if (Number.isInteger(wcCategoryId) && wcCategoryId > 0) {
  body.categories = [{ id: wcCategoryId }];
}
// 运费类映射：上架包 shipping.shipping_class = W-S 运费模板 slug，
// Woo REST 产品的 shipping_class 字段直接吃 slug 字符串。
// 没带 slug 就不写字段（保持 Woo 现值，避免覆盖手工设置）。
const shipping = pkg.shipping || {};
if (shipping.shipping_class) {
  body.shipping_class = String(shipping.shipping_class);
}
// 只有 K 显式判定为真问答的 FAQ 才能进入 schema meta。
// 旧包/缺失质量字段严格降级为空，不阻断产品上架。
const faq = Array.isArray(desc.faq) ? desc.faq : [];
const faqSchemaEligible = desc.faq_schema_eligible === true;
const faqMetaValue = faqSchemaEligible && faq.length ? JSON.stringify(faq) : '';
// Always overwrite the managed meta so an update cannot retain stale FAQ schema.
body.meta_data.push({ key: '_kp_faq', value: faqMetaValue });
return [{ json: { woo_body: body } }];

const pkg = $('取数-上架包').first().json;
if (pkg.schema_version !== 'p-upload-package-v5') {
  throw new Error('拒绝规格写入：需要 p-upload-package-v5');
}
const p = pkg.product || {};
const body = { ...$input.first().json.woo_body };
body.meta_data = Array.isArray(body.meta_data) ? [...body.meta_data] : [];
const attrs = Array.isArray(p.attributes) ? p.attributes : [];
body.attributes = attrs
  .filter((a) => a && String(a.name || '').trim() && String(a.value || '').trim())
  .map((a, index) => {
    const value = String(a.value).trim();
    const unit = typeof a.unit === 'string' ? a.unit.trim() : '';
    return {
      name: String(a.name).trim(),
      position: index,
      visible: true,
      variation: false,
      options: [unit ? value + ' ' + unit : value],
    };
  });
const managedAttributeNames = body.attributes.map((item) => item.name);
const schema = p.structured_data || {};
const properties = Array.isArray(schema.additional_property)
  ? schema.additional_property
      .filter((item) => item && String(item.name || '').trim() && String(item.value || '').trim())
      .map((item) => {
        const property = {
          '@type': 'PropertyValue',
          name: String(item.name).trim(),
          value: String(item.value).trim(),
        };
        if (typeof item.unit_text === 'string' && item.unit_text.trim()) {
          property.unitText = item.unit_text.trim();
        }
        return property;
      })
  : [];
const managedMetaKeys = new Set(['_kp_additional_property', '_kp_managed_attribute_names']);
body.meta_data = body.meta_data.filter((item) => item && !managedMetaKeys.has(item.key));
body.meta_data.push({ key: '_kp_additional_property', value: JSON.stringify(properties) });
body.meta_data.push({ key: '_kp_managed_attribute_names', value: JSON.stringify(managedAttributeNames) });
return [{ json: { woo_body: body } }];

const pkg = $('取数-上架包').first().json;
if (pkg.schema_version !== 'p-upload-package-v5') {
  throw new Error('拒绝上架：需要 p-upload-package-v5');
}
const woo_body = { ...$('添加规格与Schema').first().json.woo_body };
woo_body.meta_data = Array.isArray(woo_body.meta_data) ? [...woo_body.meta_data] : [];
const body = $input.first().json.body;
const found = (Array.isArray(body) ? body : []).filter((j) => j && j.id != null);
const existing = found.length ? found[0] : null;
const newAttributes = Array.isArray(woo_body.attributes) ? woo_body.attributes : [];
const normalizedName = (value) => String(value || '').trim().toLocaleLowerCase('en-US');
const newOwnedNames = new Set(newAttributes.map((item) => normalizedName(item.name)).filter(Boolean));
const oldOwnedNames = new Set();
if (existing && Array.isArray(existing.meta_data)) {
  const marker = existing.meta_data.find((item) => item && item.key === '_kp_managed_attribute_names');
  if (marker) {
    let names = marker.value;
    if (typeof names === 'string') {
      try { names = JSON.parse(names); } catch (_error) { names = []; }
    }
    if (Array.isArray(names)) {
      names.map(normalizedName).filter(Boolean).forEach((name) => oldOwnedNames.add(name));
    }
  }
}
if (existing) {
  const preserved = (Array.isArray(existing.attributes) ? existing.attributes : [])
    .filter((item) => {
      const name = normalizedName(item && item.name);
      return name && !oldOwnedNames.has(name) && !newOwnedNames.has(name);
    })
    .map((item) => {
      const clean = {
        name: String(item.name).trim(),
        visible: item.visible !== false,
        variation: item.variation === true,
        options: Array.isArray(item.options) ? item.options.map(String) : [],
      };
      const id = Number(item.id);
      if (Number.isInteger(id) && id > 0) clean.id = id;
      return clean;
    });
  woo_body.attributes = [...preserved, ...newAttributes].map((item, index) => ({ ...item, position: index }));
}
const base = 'https://barongyekhna.com/wp-json/wc/v3/products';
const externalId = Number(pkg.woo_existing_product_id);
if (Number.isInteger(externalId) && externalId > 0) {
  if (!existing) {
    // Identity is known but the preflight record could not be read: preserve
    // Woo attributes and their ownership marker instead of destructively clearing.
    delete woo_body.attributes;
    woo_body.meta_data = woo_body.meta_data.filter((item) => item && item.key !== '_kp_managed_attribute_names');
  }
  return [{ json: { woo_body, method: 'PUT', url: base + '/' + externalId } }];
}
const lookupSku = String(pkg.woo_lookup_sku || woo_body.sku || '');
if (existing && String(existing.sku || '') === lookupSku) {
  // Existing legacy/current SKU -> update the same Woo product; body.sku rekeys it.
  return [{ json: { woo_body, method: 'PUT', url: base + '/' + existing.id } }];
}
return [{ json: { woo_body, method: 'POST', url: base } }];
